import{_ as a,o as i,c as e,a4 as d}from"./chunks/framework.BybBnFXO.js";const _=JSON.parse('{"title":"合成品与仿品鉴别","description":"","frontmatter":{"title":"合成品与仿品鉴别","identification":"synthetic-and-imitation"},"headers":[],"relativePath":"zh/identification/synthetic-and-imitation.md","filePath":"zh/identification/synthetic-and-imitation.md","lastUpdated":1785929908000}'),n={name:"zh/identification/synthetic-and-imitation.md"};function r(o,t,h,l,c,s){return i(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="合成品与仿品鉴别" tabindex="-1">合成品与仿品鉴别 <a class="header-anchor" href="#合成品与仿品鉴别" aria-label="Permalink to &quot;合成品与仿品鉴别&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>合成宝石（同化学成分，如焰熔法红宝石、水热法祖母绿、CVD 钻石）与 仿品（不同成分，如玻璃、立方氧化锆、仿祖母绿双层石）需要不同的 鉴别路径。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>合成红/蓝宝石：焰熔法曲线生长纹、气泡；水热法含铂片/不规则包裹体。</li><li>CVD/HPHT 钻石：与天然钻石同为碳，需紫外荧光分带 + 光谱仪判断。</li><li>立方氧化锆 (CZ)：SG 5.65、异常色散、棱角锋利——与钻石区别明显。</li><li>玻璃仿品：气泡、旋涡纹、流动纹；折射率常在 1.5–1.7 区间。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>diamond</td><td>CZ (cubic zirconia)</td><td>—</td></tr><tr><td>emerald</td><td>hydrothermal</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>',8)])])}const f=a(n,[["render",r]]);export{_ as __pageData,f as default};
